(function () {
  if (window.__xzgLayerController) return;
  window.__xzgLayerController = true;

  function keepOnlyLatestAssistant() {
    try {
      var $all = $('#chat .mes').not('[mesid="0"]');
      if (!$all.length) return;
      var $assistant = $all.filter(function () {
        var $m = $(this);
        return $m.attr('is_user') !== 'true' && !$m.hasClass('is_user');
      });
      if ($assistant.length <= 1) return;
      $assistant.slice(0, -1).remove();
    } catch (e) {
      console.warn('[希望之光] 同层裁剪失败', e);
    }
  }

  function sendCmd(cmd) {
    if (!cmd) return false;
    try {
      if (typeof createChatMessages === 'function') {
        createChatMessages([{ role: 'user', message: cmd }], { insert_before: 'end', refresh: 'affected' });
        return true;
      }
    } catch (e) {
      console.warn('[希望之光] createChatMessages 发送失败，回退输入框', e);
    }

    try {
      var $ta = $('#send_textarea');
      var $btn = $('#send_but, #send_button').first();
      if (!$ta.length || !$btn.length) return false;
      $ta.val(cmd).trigger('input').trigger('change');
      $btn.trigger('click');
      return true;
    } catch (e) {
      console.warn('[希望之光] 发送命令失败', e);
      return false;
    }
  }

  window.xzgSend = sendCmd;

  function statusHtml() {
    return [
      '<div style="margin:8px 0;padding:10px;border:1px solid #3a3a3a;border-radius:8px;background:#101010;color:#ddd;">',
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">',
      '<b style="color:#e8b86d;">🏥 希望之光 · 状态总面板（内置降级版）</b>',
      '<span style="color:#888;font-size:12px;">点击按钮发送命令</span>',
      '</div>',
      '<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;">',
      '<button data-cmd="【查看状态总览】">状态总览</button>',
      '<button data-cmd="【查看当前任务】">查看任务</button>',
      '<button data-cmd="【推进任务】">推进任务</button>',
      '<button data-cmd="【班次结算】">班次结算</button>',
      '<button data-cmd="【查看风险评分】">风险评分</button>',
      '<button data-cmd="【查看判定细节】">判定细节</button>',
      '</div>',
      '</div>',
    ].join('');
  }

  function mountIntro() {
    return;
  }

  function mountStatus() {
    var $a = $('[data-hopesim-status-anchor="1"]').first();
    if (!$a.length || $a.attr('data-xzg-status-mounted') === '1') return;
    $a.attr('data-xzg-status-mounted', '1');
    $a.html(statusHtml());
    $a.find('button[data-cmd]').each(function () {
      this.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var cmd = (this.getAttribute('data-cmd') || '').trim();
        cmd && sendCmd(cmd);
      });
    });
  }

  $(document).off('click.xzgGlobal').on('click.xzgGlobal', 'button[data-cmd], [data-cmd].btn, [data-cmd].cmd', function (e) {
    var cmd = ($(this).attr('data-cmd') || '').trim();
    if (!cmd) return;
    e.preventDefault();
    e.stopPropagation();
    sendCmd(cmd);
  });

  var tick = 0;
  var timer = window.setInterval(function () {
    tick += 1;
    mountIntro();
    mountStatus();
    keepOnlyLatestAssistant();
    if (tick > 120) window.clearInterval(timer);
  }, 250);

  if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
    eventOn(tavern_events.MESSAGE_RECEIVED, function () {
      setTimeout(keepOnlyLatestAssistant, 80);
    });
    eventOn(tavern_events.MESSAGE_SENT, function () {
      setTimeout(keepOnlyLatestAssistant, 80);
    });
    eventOn(tavern_events.MESSAGE_DELETED, function () {
      setTimeout(keepOnlyLatestAssistant, 80);
    });
  }
})();

